<?php
require_once __DIR__ . '/../config/config.php';
requireCrmPanel(['admin']);
requirePermission('publish_reviews');
$reviewObj=new OrderReview();$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){requireCsrf();$result=$reviewObj->moderate((int)($_POST['review_id']??0),(int)$_SESSION['user_id'],$_POST['status']??'rejected');$success=$result['success']?'Статус отзыва сохранён':'';$error=$result['success']?'':$result['error'];}
$reviews=dbColumnExists('reviews','order_id')?$reviewObj->pendingModeration():[];
?>
<!DOCTYPE html><html lang="ru"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>Модерация отзывов - Азбука Декора</title><link rel="stylesheet" href="<?php echo asset('assets/css/style.min.css'); ?>"><?php include_once __DIR__ . '/../includes/favicon-links.php'; ?></head><body><?php include_once __DIR__.'/../includes/organizer-header.php';?><main class="dashboard"><div class="container"><div class="dashboard-header"><div><p class="eyebrow">Обратная связь</p><h1>Модерация отзывов</h1></div></div><?php if($error):?><div class="alert alert-error"><?php echo escape($error);?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?php echo escape($success);?></div><?php endif;?><div class="review-admin-grid"><?php foreach($reviews as $review):?><article class="review-admin-card"><span class="badge"><?php echo escape($review['status']);?></span><h2><?php echo escape($review['client_name']?:'Клиент');?></h2><p><?php echo escape($review['order_title']);?></p><p class="review-rating"><?php echo (int)$review['rating'];?> / 5</p><blockquote><?php echo nl2br(escape($review['text']));?></blockquote><p class="muted">Публикация: <?php echo $review['publication_consent']?'разрешена':'не разрешена';?> · Фото: <?php echo $review['photo_consent']?'разрешены':'не разрешены';?></p><form method="POST" class="inline-form"><?php echo csrfField();?><input type="hidden" name="review_id" value="<?php echo (int)$review['id'];?>"><label class="sr-only" for="review-status-<?php echo (int)$review['id']; ?>">Статус отзыва клиента <?php echo escape($review['client_name'] ?: 'без имени'); ?></label><select id="review-status-<?php echo (int)$review['id']; ?>" name="status" class="form-control"><option value="approved">Одобрить</option><option value="rejected">Отклонить</option><option value="published">Опубликовать</option></select><button class="btn btn-primary">Сохранить</button></form></article><?php endforeach;?></div></div></main><?php include_once __DIR__.'/../includes/organizer-footer.php';?></body></html>
